-- Controlled first-pass ITG roster import from the donor application.
--
-- The platform roster remains authoritative. Telecom identifiers use the same
-- extensible identifier contract as the existing commercial product. This load
-- is idempotent by donor person ID and preserves donor assignment context in the
-- roster event ledger.
--
-- Imported scope:
--   * 37 active ITG assignments in PC 410 and PC 427;
--   * 1 active ITG director person required by the reporting hierarchy;
--   * no contractor or Locate records.

create temporary table itf_itg_roster_source (
  source_person_id uuid primary key,
  source_assignment_id uuid,
  full_name text not null,
  email text,
  phone text,
  tech_id text,
  fuse_emp_id text,
  nt_login text,
  csg text,
  location_code text,
  position_title text,
  role_type text,
  is_field boolean not null,
  is_leadership boolean not null,
  start_date date,
  end_date date,
  office_name text,
  reports_to_source_person_id uuid,
  reports_to_name text,
  link_platform_owner boolean not null,
  target_roster_id uuid
) on commit drop;

insert into itf_itg_roster_source (
  source_person_id,
  source_assignment_id,
  full_name,
  email,
  phone,
  tech_id,
  fuse_emp_id,
  nt_login,
  csg,
  location_code,
  position_title,
  role_type,
  is_field,
  is_leadership,
  start_date,
  end_date,
  office_name,
  reports_to_source_person_id,
  reports_to_name,
  link_platform_owner
)
select
  source_person_id,
  source_assignment_id,
  full_name,
  email,
  phone,
  tech_id,
  fuse_emp_id,
  nt_login,
  csg,
  location_code,
  position_title,
  role_type,
  is_field,
  is_leadership,
  start_date,
  end_date,
  office_name,
  reports_to_source_person_id,
  reports_to_name,
  link_platform_owner
from jsonb_to_recordset(
  convert_from(decode('', 'base64'), 'utf8')::jsonb
) as source_row (
  source_person_id uuid,
  source_assignment_id uuid,
  full_name text,
  email text,
  phone text,
  tech_id text,
  fuse_emp_id text,
  nt_login text,
  csg text,
  location_code text,
  position_title text,
  role_type text,
  is_field boolean,
  is_leadership boolean,
  start_date date,
  end_date date,
  office_name text,
  reports_to_source_person_id uuid,
  reports_to_name text,
  link_platform_owner boolean
);

do $$
declare
  v_company_id uuid;
  v_location_count integer;
begin
  select company.id
  into v_company_id
  from core.companies company
  where company.company_slug = 'integrated-tech-group'
    and company.company_status = 'active';

  if v_company_id is null then
    raise exception 'Integrated Tech Group company foundation is missing.';
  end if;

  if (select count(*) from itf_itg_roster_source) <> 38 then
    raise exception 'Expected 38 controlled ITG roster rows.';
  end if;

  if exists (
    select 1
    from itf_itg_roster_source source
    where source.location_code is not null
      and source.location_code not in ('410', '427')
  ) then
    raise exception 'ITG roster source contains an unauthorized location.';
  end if;

  select count(*)
  into v_location_count
  from core.company_location location
  where location.company_id = v_company_id
    and location.location_code in ('410', '427')
    and location.location_status = 'active';

  if v_location_count <> 2 then
    raise exception 'ITG locations 410 and 427 must both be active.';
  end if;

  if not exists (
    select 1
    from core.profiles profile
    where profile.is_platform_owner
  ) then
    raise exception 'A platform owner profile is required to record import provenance.';
  end if;
end;
$$;

update itf_itg_roster_source source
set target_roster_id = coalesce(
  (
    select provenance.roster_id
    from core.company_roster_entry_provenance provenance
    where provenance.source_system = 'itg-insight'
      and provenance.source_record_id = source.source_person_id::text
  ),
  gen_random_uuid()
);

insert into core.company_roster (
  id,
  company_id,
  profile_id,
  full_name,
  email,
  phone,
  worker_type,
  job_title,
  employment_status,
  company_location_id,
  hire_date,
  separation_date,
  invite_status,
  compliance_summary,
  notes,
  roster_record_kind
)
select
  source.target_roster_id,
  company.id,
  case
    when source.link_platform_owner then (
      select profile.id
      from core.profiles profile
      where profile.is_platform_owner
      order by profile.created_at
      limit 1
    )
    else null
  end,
  btrim(source.full_name),
  nullif(lower(btrim(coalesce(source.email, ''))), ''),
  nullif(btrim(coalesce(source.phone, '')), ''),
  nullif(btrim(coalesce(source.role_type, '')), ''),
  nullif(btrim(coalesce(source.position_title, '')), ''),
  'Active',
  location.id,
  source.start_date,
  null,
  case when source.link_platform_owner then 'Linked' else 'Not Invited' end,
  'Missing',
  null,
  'INTERNAL'
from itf_itg_roster_source source
cross join lateral (
  select company.id
  from core.companies company
  where company.company_slug = 'integrated-tech-group'
    and company.company_status = 'active'
) company
left join core.company_location location
  on location.company_id = company.id
 and location.location_code = source.location_code
 and location.location_status = 'active'
on conflict (id) do update
set
  profile_id = excluded.profile_id,
  full_name = excluded.full_name,
  email = excluded.email,
  phone = excluded.phone,
  worker_type = excluded.worker_type,
  job_title = excluded.job_title,
  employment_status = excluded.employment_status,
  company_location_id = excluded.company_location_id,
  hire_date = excluded.hire_date,
  separation_date = excluded.separation_date,
  invite_status = excluded.invite_status,
  roster_record_kind = excluded.roster_record_kind;

insert into core.company_roster_entry_provenance (
  roster_id,
  roster_owner_company_id,
  entry_authority,
  entry_channel,
  entered_by_company_id,
  entered_by_profile_id,
  source_system,
  source_record_id
)
select
  source.target_roster_id,
  company.id,
  'owner_company',
  'donor_migration',
  company.id,
  actor.id,
  'itg-insight',
  source.source_person_id::text
from itf_itg_roster_source source
cross join lateral (
  select company.id
  from core.companies company
  where company.company_slug = 'integrated-tech-group'
) company
cross join lateral (
  select profile.id
  from core.profiles profile
  where profile.is_platform_owner
  order by profile.created_at
  limit 1
) actor
on conflict (roster_id) do nothing;

insert into core.company_roster_identifier (
  roster_id,
  identifier_type,
  identifier_value
)
select
  source.target_roster_id,
  identifier.identifier_type,
  identifier.identifier_value
from itf_itg_roster_source source
cross join lateral (
  values
    ('tech_id'::text, case when source.link_platform_owner then null else nullif(btrim(coalesce(source.tech_id, '')), '') end),
    ('fuse_emp_id'::text, nullif(btrim(coalesce(source.fuse_emp_id, '')), '')),
    ('nt_login'::text, nullif(btrim(coalesce(source.nt_login, '')), '')),
    ('csg'::text, nullif(btrim(coalesce(source.csg, '')), '')),
    ('legacy_person_id'::text, source.source_person_id::text),
    ('legacy_assignment_id'::text, source.source_assignment_id::text)
) identifier(identifier_type, identifier_value)
where identifier.identifier_value is not null
on conflict (roster_id, identifier_type) do update
set identifier_value = excluded.identifier_value;

update core.company_roster child
set reports_to_roster_id = parent.target_roster_id
from itf_itg_roster_source source
join itf_itg_roster_source parent
  on parent.source_person_id = source.reports_to_source_person_id
where child.id = source.target_roster_id
  and child.reports_to_roster_id is distinct from parent.target_roster_id;

insert into core.company_roster_event (
  company_id,
  roster_id,
  event_category,
  event_type,
  event_detail,
  event_metadata,
  occurred_at,
  created_by_profile_id
)
select
  company.id,
  source.target_roster_id,
  'system',
  'donor_roster_imported',
  'ITG roster record imported from the donor application.',
  jsonb_strip_nulls(jsonb_build_object(
    'source_system', 'itg-insight',
    'source_person_id', source.source_person_id,
    'source_assignment_id', source.source_assignment_id,
    'location_code', source.location_code,
    'office_name', source.office_name,
    'position_title', source.position_title,
    'role_type', source.role_type,
    'is_field', source.is_field,
    'is_leadership', source.is_leadership,
    'reports_to_source_person_id', source.reports_to_source_person_id,
    'reports_to_name', source.reports_to_name
  )),
  now(),
  actor.id
from itf_itg_roster_source source
cross join lateral (
  select company.id
  from core.companies company
  where company.company_slug = 'integrated-tech-group'
) company
cross join lateral (
  select profile.id
  from core.profiles profile
  where profile.is_platform_owner
  order by profile.created_at
  limit 1
) actor
where not exists (
  select 1
  from core.company_roster_event event
  where event.roster_id = source.target_roster_id
    and event.event_type = 'donor_roster_imported'
);

create or replace view public.itf_company_roster_v
with (security_invoker = true)
as
select
  roster.id as roster_member_id,
  roster.company_id,
  company.company_name,
  company.company_slug,
  roster.profile_id,
  roster.full_name,
  roster.email,
  roster.phone,
  roster.worker_type,
  roster.job_title,
  roster.employment_status,
  roster.company_location_id,
  location.location_code,
  location.location_name,
  roster.reports_to_roster_id,
  supervisor.full_name as reports_to_name,
  identifiers.tech_id,
  identifiers.fuse_emp_id,
  identifiers.nt_login,
  identifiers.csg,
  identifiers.legacy_person_id,
  identifiers.legacy_assignment_id,
  import_event.event_metadata ->> 'office_name' as donor_office_name,
  provenance.entry_channel,
  provenance.source_system,
  provenance.source_record_id,
  case
    when provenance.entry_channel = 'donor_migration' then 'Donor import'
    when provenance.entered_by_company_id = roster.company_id then 'Company added'
    else 'Added on behalf'
  end as source_label
from core.company_roster roster
join core.companies company
  on company.id = roster.company_id
join core.company_product company_product
  on company_product.company_id = company.id
 and company_product.participation_status in ('active', 'review')
join ref.insight_products product
  on product.id = company_product.product_id
 and product.product_key = 'insight-telecom-fulfillment'
left join core.company_location location
  on location.id = roster.company_location_id
left join core.company_roster supervisor
  on supervisor.id = roster.reports_to_roster_id
left join core.company_roster_entry_provenance provenance
  on provenance.roster_id = roster.id
left join lateral (
  select
    max(identifier.identifier_value) filter (where identifier.identifier_type = 'tech_id') as tech_id,
    max(identifier.identifier_value) filter (where identifier.identifier_type = 'fuse_emp_id') as fuse_emp_id,
    max(identifier.identifier_value) filter (where identifier.identifier_type = 'nt_login') as nt_login,
    max(identifier.identifier_value) filter (where identifier.identifier_type = 'csg') as csg,
    max(identifier.identifier_value) filter (where identifier.identifier_type = 'legacy_person_id') as legacy_person_id,
    max(identifier.identifier_value) filter (where identifier.identifier_type = 'legacy_assignment_id') as legacy_assignment_id
  from core.company_roster_identifier identifier
  where identifier.roster_id = roster.id
) identifiers on true
left join lateral (
  select event.event_metadata
  from core.company_roster_event event
  where event.roster_id = roster.id
    and event.event_type = 'donor_roster_imported'
  order by event.occurred_at desc, event.created_at desc
  limit 1
) import_event on true;

comment on view public.itf_company_roster_v is
  'Company-authorized ITF roster projection composed from the platform roster, telecom identifiers, location, reporting line, and provenance.';

revoke all on table public.itf_company_roster_v from anon;
grant select on table public.itf_company_roster_v to authenticated;

do $$
declare
  v_company_id uuid;
  v_total integer;
  v_410 integer;
  v_427 integer;
  v_reporting_links integer;
begin
  select company.id
  into v_company_id
  from core.companies company
  where company.company_slug = 'integrated-tech-group';

  select count(*)
  into v_total
  from core.company_roster_entry_provenance provenance
  where provenance.roster_owner_company_id = v_company_id
    and provenance.source_system = 'itg-insight';

  select
    count(*) filter (where roster.location_code = '410'),
    count(*) filter (where roster.location_code = '427'),
    count(*) filter (where roster.reports_to_roster_id is not null)
  into v_410, v_427, v_reporting_links
  from public.itf_company_roster_v roster
  where roster.company_id = v_company_id;

  if v_total <> 38 or v_410 <> 12 or v_427 <> 25 then
    raise exception 'ITG roster import parity failed: total %, 410 %, 427 %.',
      v_total, v_410, v_427;
  end if;

  if v_reporting_links <> 35 then
    raise exception 'ITG reporting hierarchy parity failed: expected 35 links, found %.',
      v_reporting_links;
  end if;
end;
$$;
